import type { Document } from '../services/documentService';

export interface ExtractedVerificationFields {
  vendorName: string;
  date: string;
  gstin: string;
  invoiceNumber: string;
}

export interface BillTransactionPreviewRow {
  id: string;
  description: string;
  amount: number;
}

export interface ExtractedDataVerificationState {
  status: 'pending' | 'verified';
  acceptedForEmissions: boolean;
  verifiedAt?: string | null;
  correctionCount?: number;
}

const resolveItemAmount = (item: {
  total?: number;
  price?: number;
  quantity?: number;
}): number => {
  const total = Number(item.total);
  if (Number.isFinite(total) && total > 0) {
    return total;
  }
  const price = Number(item.price);
  const quantity = Number(item.quantity);
  if (Number.isFinite(price) && Number.isFinite(quantity) && price > 0 && quantity > 0) {
    return price * quantity;
  }
  return Number.isFinite(price) && price > 0 ? price : 0;
};

const formatDateForInput = (value?: string | Date | null): string => {
  if (!value) {
    return '';
  }
  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return '';
  }
  return parsed.toISOString().slice(0, 10);
};

export const readGstin = (document: Document): string => {
  const data = document.extractedData;
  if (!data) {
    return '';
  }
  return String(data.gstin || data.seller_gstin || '').trim();
};

export const readInvoiceNumber = (document: Document): string => {
  const data = document.extractedData;
  if (!data) {
    return '';
  }
  return String(data.referenceNumber || data.invoice_number || '').trim();
};

export const getBillTransactionPreview = (document: Document): BillTransactionPreviewRow[] => {
  const extractedData = document.extractedData;
  if (!extractedData) {
    return [];
  }

  const items = Array.isArray(extractedData.items) ? extractedData.items : [];
  if (items.length > 0) {
    return items
      .map((item, index) => {
        const description = String(item.name || 'Line item').trim() || 'Line item';
        const amount = resolveItemAmount(item);
        return {
          id: `item-${index}`,
          description,
          amount,
        };
      })
      .filter((row) => row.amount > 0 || row.description);
  }

  const amount = Number(extractedData.amount);
  if (Number.isFinite(amount) && amount > 0) {
    return [{
      id: 'document-total',
      description: String(extractedData.description || 'Bill total').trim() || 'Bill total',
      amount,
    }];
  }

  return [];
};

export const getBillTransactionTotal = (rows: BillTransactionPreviewRow[]): number =>
  rows.reduce((sum, row) => sum + (Number.isFinite(row.amount) ? row.amount : 0), 0);

export const formatBillAmount = (amount: number): string =>
  `₹${amount.toLocaleString('en-IN', { maximumFractionDigits: 2 })}`;

export const getExtractedVerificationFields = (document: Document): ExtractedVerificationFields => ({
  vendorName: document.extractedData?.vendor?.name?.trim() || '',
  date: formatDateForInput(document.extractedData?.date),
  gstin: readGstin(document),
  invoiceNumber: readInvoiceNumber(document),
});

export const getExtractedDataVerificationState = (
  document: Document
): ExtractedDataVerificationState => ({
  status: document.extractedDataVerification?.status === 'verified' ? 'verified' : 'pending',
  acceptedForEmissions: Boolean(document.extractedDataVerification?.acceptedForEmissions),
  verifiedAt: document.extractedDataVerification?.verifiedAt || null,
  correctionCount: document.extractedDataVerification?.correctionCount || 0,
});

export const shouldShowExtractedDataVerification = (document: Document): boolean =>
  document.status === 'processed'
  && Boolean(document.extractedData)
  && !document.duplicateDetection?.isDuplicate;

export const isExtractedDataVerified = (document: Document): boolean =>
  document.extractedDataVerification?.status === 'verified'
  && Boolean(document.extractedDataVerification?.acceptedForEmissions);
